catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var bindAddress = g_form.getValue('bind_address').trim();
    var bindPort = g_form.getValue('bind_port').trim();

    // Clear previous messages
    g_form.hideFieldMsg('bind_address', true);
    g_form.hideFieldMsg('bind_port', true);

    if (!bindAddress || !bindPort) {
        g_form.setValue('validation_message', ''); // Optional clear
        return;
    }

    // Show "Validating..." while GlideAjax runs
    g_form.showFieldMsg('bind_address', 'Validating...', 'info');
    g_form.showFieldMsg('bind_port', 'Validating...', 'info');

    var ga = new GlideAjax('GetDeviceCertificateDetails');
    ga.addParam('sysparm_name', 'getDeviceDetails');
    ga.addParam('sysparm_deviceSysId', g_form.getValue('device'));
    ga.addParam('sysparm_bindAddress', bindAddress);
    ga.addParam('sysparm_bindPort', bindPort);

    ga.getXMLAnswer(function(response) {
        // Clear loading messages
        g_form.hideFieldMsg('bind_address', true);
        g_form.hideFieldMsg('bind_port', true);

        try {
            var res = JSON.parse(response);

            if (res.error) {
                g_form.showFieldMsg('bind_address', res.error, 'error');
				g_form.showFieldMsg('bind_port', res.error, 'error');
                g_form.setValue('validation_message', 'error');
            } else if (res.length > 0) {
                g_form.showFieldMsg('bind_address', 'Conflict: Bind Address and Port already exist.', 'error');
				g_form.showFieldMsg('bind_port', 'Conflict: Bind Address and Port already exist.', 'error');
                g_form.setValue('validation_message', 'error');
            } else {
                g_form.setValue('validation_message', 'success');
            }
        } catch (e) {
            g_form.showFieldMsg('bind_address', 'Validation failed.', 'error');
            g_form.setValue('validation_message', 'error');
        }
    });

}
